class Solution:
    def reverseKGroup(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        node = head
        for _ in range(k):
            if not node:
                return head
            node = node.next
        prev, cur = self.reverseKGroup(node, k), head
        for _ in range(k):
            cur.next, prev, cur = prev, cur, cur.next
        return prev

